/* ===== bbee-inspector 0.4.0: live action / input / skill-chain / hit / effect inspector + diagnostic capture =====
   Developer tool (optional mod). Appended to data/js/window/battle/BattleUI; BattleUI.UpdateWindow calls BBI_Tick
   every frame during battle. Everything here READS the game except the pause / speed keys, which change the real
   simulation (Battle.TimeScale), not just what is shown.
   Keys (keyboard, in battle):
     F8  overlay off -> light -> detail           F9  mark this moment + export a report to <workspace>/diag
     F10 pause / resume the simulation            F11 step the simulation one frame while paused
     F7  simulation speed x1 -> x0.5 -> x0.25     F6  effect filter: this character only / everything
   History (inputs, skills, actions, hits, effects, warnings) is recorded whether or not the overlay is shown.
   Docs: docs/tools/INSPECTOR.md */
(function () {
  var G = globalThis; if (G.BBI_Tick) return;
  var CS = csharp_1, U = Util_1.U, ROOT = "@ROOT@", DIAG = ROOT + "/diag", VERSION = "0.4.0";
  var CMD = [[1, "Attack"], [3, "Skill"], [55, "Dash"], [800, "Jump"], [5, "Summon"]];
  var GRP = [1, 2, 3, 4, 5, 7, 8, 11];
  var GN = { 1: "Attack", 2: "Skill", 3: "Ultra", 4: "Air", 5: "Dash", 7: "Jump", 8: "Hold", 11: "Summon" };
  var STN = { 0: "idle", 2: "active", 4: "cooldown", 5: "inactive" };
  var SPD = [1, 0.5, 0.25], MAXH = 900, MAXS = 240;
  var S = { mode: 0, hist: [], warn: [], samples: [], aid: null, act: null, press: {}, chain: {}, fx: [], fxq: [],
            hooked: false, frame: 0, stepping: 0, spd: 0, paused: false, note: "", noteT: -9, mineOnly: true,
            hitT: NaN, behitT: NaN, skillFr: {}, marks: 0, pname: null, pending: null, shown: false, lastSample: -9 };
  G.BBI = S;   // for other dev tools

  // ---- continuous trace (0.4.0) ---------------------------------------------------------------------------------
  // When <workspace>/diag/trace_on exists, every event (and a position sample 10 times a second) is also appended to
  // diag/trace_<date>_<time>.jsonl, flushed once a second: a test session is fully logged without pressing F9, so a
  // screen recording can be matched to actions, effect spawns, hits and her position / facing (Cross Effect, Test 5).
  var TR = { on: null, buf: [], last: 0, file: null, ls: -9 };
  function traceOn() {
    if (TR.on === null) { try { TR.on = !!CS.System.IO.File.Exists(DIAG + "/trace_on") } catch (e) { TR.on = false } }
    return TR.on;
  }
  function traceFlush(force) {
    if (!traceOn() || !TR.buf.length) return;
    var t = Date.now(); if (!force && t - TR.last < 1000) return; TR.last = t;
    try {
      if (!TR.file) {
        var d = new Date();
        TR.file = DIAG + "/trace_" + d.getFullYear() + pad(d.getMonth() + 1) + pad(d.getDate()) + "_" + pad(d.getHours()) + pad(d.getMinutes()) + pad(d.getSeconds()) + ".jsonl";
        CS.System.IO.Directory.CreateDirectory(DIAG);
      }
      CS.System.IO.File.AppendAllText(TR.file, TR.buf.map(function (o) { return JSON.stringify(o) }).join("\n") + "\n");
    } catch (e) { TR.on = false; note("trace write failed: " + e) }
    TR.buf = [];
  }
  function posTick(p) {
    try { var v = p.Position; S.px = r3(v.x); S.py = r3(v.y) } catch (e) { S.px = S.py = null }
    try { S.dir = r3(p.Dir) } catch (e) { S.dir = null }
  }

  // ---- helpers -----------------------------------------------------------------------------------------------
  // Fp is a struct around a 64-bit `value` (value / 2^32). U.FpToFloat returned NaN here in every 0.2.0 report, so the
  // raw field is read as a fallback (Puerts hands a long over as a BigInt or a Number).
  function f(v) {
    var x = NaN;
    try { x = U.FpToFloat(v) } catch (e) {}
    if (!(typeof x === "number" && isFinite(x))) { try { x = Number(v.value) / 4294967296 } catch (e) { x = NaN } }
    return (typeof x === "number" && isFinite(x)) ? x : NaN;
  }
  function r3(x) { return (typeof x === "number" && isFinite(x)) ? Math.round(x * 1000) / 1000 : x }
  function B() { try { return CS.GamePlay.BattleBase.Cur } catch (e) { return null } }
  // battle clock; if it can't be read, seconds since the inspector started (the report header says which one)
  function now() {
    var b = B(), t = b ? f(b.BattleTimeFp) : NaN;
    if (isFinite(t)) { S.clock = "battle"; return t }
    if (!S.w0) S.w0 = Date.now();
    S.clock = "wall"; return (Date.now() - S.w0) / 1000;
  }
  function push(k, o) {
    o = o || {}; o.k = k; o.t = r3(now()); o.fr = S.frame; o.wall = Date.now();
    if (k === "act" || k === "fx+" || k === "hit" || k === "in") { o.x = S.px; o.y = S.py; o.dir = S.dir }
    S.hist.push(o); if (S.hist.length > MAXH) S.hist.shift();
    if (traceOn()) TR.buf.push(o);
    return o;
  }
  function warn(msg) { var o = push("WARN", { msg: msg }); S.warn.push(o); if (S.warn.length > 80) S.warn.shift() }
  function note(msg) { S.note = msg; S.noteT = now() }
  var KC = null;
  function down(name) { try { if (!KC) KC = CS.UnityEngine.KeyCode; return CS.UnityEngine.Input.GetKeyDown(KC[name]) } catch (e) { return false } }

  // ---- what the character is doing ---------------------------------------------------------------------------
  function actorInfo(p) {
    var o = { id: 0, uid: 0, action: "", logic: "" };
    try { o.id = p.BaseID } catch (e) {}
    try { o.uid = p.UniqueId } catch (e) {}
    try { o.action = p.ActionMgr.CurrentActionName } catch (e) {}
    try { o.logic = p.ActionMgr.ActionGroup.name } catch (e) {}
    return o;
  }
  function actionTick(p) {
    var am = null; try { am = p.ActionMgr } catch (e) {}
    if (!am) return;
    var id = null, nm = "", el = NaN, dur = NaN, ty = -1;
    try { id = am.ActionChangeAutoId; nm = am.CurrentActionName; el = f(am.Time); dur = f(am.CurrentActionDuration); ty = am.CurrentActionType } catch (e) {}
    if (id !== S.aid) {
      var prev = S.act;
      push("act", prev ? { name: nm, from: prev.name, ranFor: r3(prev.el), of: r3(prev.dur), type: ty } : { name: nm, type: ty });
      S.aid = id; S.act = { name: nm, el: el, dur: dur, type: ty, t0: now() };
    } else if (S.act) { S.act.el = el; S.act.dur = dur }
  }

  // ---- skill chains (the engine's rules, read from PlayerSkillChain) -----------------------------------------
  function chains(p) {
    var out = {};
    for (var i = 0; i < GRP.length; i++) {
      var g = GRP[i], c = null;
      try { c = p.SkillMgr.get_Item(g) } catch (e) {}
      if (!c) continue;
      var o = { g: g, st: 0, act: "", ord: 0, el: 0, strict: 0, to: 0, mute: 0, cd: 0, n: 0, inp: 0 };
      try { o.st = c.Status; o.mute = r3(f(c.MuteRemain)); o.cd = r3(f(c.CoolDownRemain)); o.n = c.CastTimes; o.inp = c.Input } catch (e) {}
      try {
        var cur = c.Cur, sk = cur ? cur.Skill : null;
        if (sk) { o.act = cur.Action; o.ord = cur.Order; o.el = r3(f(cur.TimeEllaps)); var sa = sk.SkillActivate;
                  o.strict = r3(f(sa.ActdurStrict)); o.to = r3(f(sa.Timeout)) }
      } catch (e) {}
      out[g] = o;
    }
    return out;
  }
  function locks(p) {
    var o = { stun: false, lockAtk: false };
    try { var a = p.BuffMgr.BuffAttr; o.stun = !!a.Stun; o.lockAtk = !!a.LockInputAttack } catch (e) {}
    return o;
  }
  // why a fresh press is not (yet) turning into a skill: PlayerSkillMgr skips every chain while Stun / LockInputAttack;
  // a chain reads input only when not on cooldown, not muted, and its running step has lasted ActdurStrict
  function reasonFor(ch, cmd, lk) {
    if (lk.stun) return "all skill input blocked: stunned (buff)";
    if (lk.lockAtk) return "all skill input blocked: LockInputAttack (buff)";
    var owners = [];
    for (var g in ch) if (ch[g].inp === cmd) owners.push(ch[g]);
    if (!owners.length) return "no skill chain listens to this input";
    var blocked = [], ready = [];
    for (var i = 0; i < owners.length; i++) {
      var o = owners[i], nm = GN[o.g] + " chain";
      if (o.st === 4) blocked.push(nm + " on cooldown " + o.cd + "s");
      else if (o.st === 5) blocked.push(nm + " inactive");
      else if (o.mute > 0) blocked.push(nm + " muted " + o.mute + "s (lockout from the previous skill)");
      else if (o.act && o.el < o.strict) blocked.push(nm + ": " + o.act + " not at its cancel point yet (" + o.el + "/" + o.strict + "s)");
      else ready.push(nm + " ready, no row matched" + (o.act ? " after " + o.act : "") + " (direction / ground-air / MP / follow-up)");
    }
    return blocked.concat(ready).join("; ");
  }
  function chainTick(ch) {
    for (var g in ch) {
      var o = ch[g], prev = S.chain[g];
      if (prev && (o.n !== prev.n || (o.act && (o.act !== prev.act || o.ord !== prev.ord)))) {
        push("skill", { g: +g, grp: GN[g], act: o.act, ord: o.ord, prev: prev.act, prevEl: prev.el, prevStrict: prev.strict });
        for (var i = 0; i < CMD.length; i++) if (CMD[i][0] === o.inp) {
          var P = S.press[CMD[i][1]];
          if (P && P.open) { P.open = false; push("used", { cmd: CMD[i][1], after: r3(now() - P.at), by: o.act }) }
        }
        S.pending = { act: o.act, fr: S.frame };   // the action should change to it within a frame or two
        S.skillFr[o.inp] = S.frame;                 // a press arriving this same frame was used by this skill
      }
      if (prev && prev.st !== o.st) push("chain", { grp: GN[g], st: STN[o.st] || o.st, act: o.act, cd: o.cd });
      S.chain[g] = o;
    }
    if (S.pending && S.frame - S.pending.fr >= 3) {
      if (S.act && S.act.name !== S.pending.act) warn("skill " + S.pending.act + " started but the action is " + S.act.name + " (transition failed or was replaced)");
      S.pending = null;
    }
  }

  // ---- inputs: every press, whether it was used, and why not -------------------------------------------------
  function inputTick(p, ch) {
    var lk = locks(p);
    for (var i = 0; i < CMD.length; i++) {
      var cmd = CMD[i][0], nm = CMD[i][1], st = null;
      try { st = p.Input.GetCmdStatus(cmd) } catch (e) {}
      if (!st) continue;
      var lp = NaN, sat = false, pr = false;
      try { lp = f(st.LastPressTimeStamp); sat = !!st.PressInputSatisfied; pr = !!st.Pressing } catch (e) {}
      var P = S.press[nm];
      if (!P) { S.press[nm] = { lp: lp, sat: sat, pr: pr, open: false }; continue }
      if (lp !== P.lp && isFinite(lp)) {
        var still = P.open; P.lp = lp; P.at = now(); P.open = true; P.seen = {}; P.sat = sat;
        push("in", { cmd: nm, during: S.act ? S.act.name : "", at: S.act ? r3(S.act.el) : 0, of: S.act ? r3(S.act.dur) : 0,
                     prevWaiting: still });
        if (S.skillFr[cmd] === S.frame) { P.open = false; push("used", { cmd: nm, after: 0 }) }
      }
      if (P.open) {
        var why = reasonFor(ch, cmd, lk); P.seen[why] = (P.seen[why] || 0) + 1;
        if (sat && !P.sat) { P.open = false; push("used", { cmd: nm, after: r3(now() - P.at) }) }
        else if (now() - P.at > 0.5) {
          P.open = false; var best = "", n = -1;
          for (var w in P.seen) if (P.seen[w] > n) { n = P.seen[w]; best = w }
          warn(nm + " press at t=" + r3(P.at) + " (during " + (S.act ? S.act.name : "?") + ") never became a skill: " + best);
        }
      }
      P.sat = sat; P.pr = pr;
    }
  }

  // ---- hits given and taken ---------------------------------------------------------------------------------
  function hitTick(p) {
    var ts = NaN; try { ts = f(p.LastHitResultInCurActionTimeStamp) } catch (e) {}
    if (isFinite(ts) && ts !== S.hitT) {
      S.hitT = ts; var a = null, o = { by: S.act ? S.act.name : "", tgt: "", react: "", dmg: NaN, grp: "", move: "" };
      try { a = p.LastHitResultInCurAction } catch (e) {}
      if (a) {
        try { o.dmg = r3(f(a.DamageTotal)) } catch (e) {}
        try { var tg = a.Target; o.tgt = String(tg.UniqueId); o.react = tg.ActionMgr.CurrentActionName } catch (e) {}
        try { var k = a.Ssss.SkillActivate; if (k) { o.grp = GN[k.Group] || k.Group; o.move = k.Action } } catch (e) {}
      }
      push("hit", o);
    }
    var bt = NaN; try { bt = f(p.LastBehitTimeStamp) } catch (e) {}
    if (isFinite(bt) && bt !== S.behitT) { if (isFinite(S.behitT)) push("hurt", { during: S.act ? S.act.name : "" }); S.behitT = bt }
  }

  // ---- effects: spawn (engine hook), owner / attachment, and when they end ---------------------------------------
  function hookFx() {
    S.hooked = true;
    try {
      var m = U.GetSingleton(CS.NOAH.VFX.VFXManager);
      m.add_PreprocessEffect(function (hub) { if (S.fxq.length < 300) S.fxq.push({ hub: hub, t: now(), act: S.act ? S.act.name : "" }) });
      push("info", { msg: "effect hook installed" });
    } catch (e) { warn("effect hook unavailable: " + e) }
  }
  function playerRoot(p) {
    if (S.pname !== null) return S.pname;
    var cands = [function () { return p.ActorModel.transform.root.name }, function () { return p.SmoothObject.transform.root.name },
                 function () { return p.ActorModel.gameObject.transform.root.name }];
    for (var i = 0; i < cands.length; i++) { try { var v = cands[i](); if (v) { S.pname = v; return v } } catch (e) {} }
    S.pname = ""; return "";
  }
  function fxTick(p) {
    var mine = playerRoot(p);
    while (S.fxq.length) {
      var q = S.fxq.shift(), prm = null, nm = "?", tgt = "(world)", root = "", bind = false, keep = false;
      try { prm = q.hub.Param } catch (e) {}
      try { nm = prm.name } catch (e) {}
      try { if (prm.target) { root = prm.target.root.name; tgt = root + "/" + prm.target.name } } catch (e) {}
      try { bind = !!prm.bind; keep = !!prm.dontStop } catch (e) {}
      var own = !!(mine && root === mine);
      if (S.mineOnly && mine && !own) continue;
      push("fx+", { name: nm, on: tgt, bind: bind, keep: keep, act: q.act, own: own });
      S.fx.push({ hub: q.hub, name: nm, t: q.t, act: q.act, own: own }); if (S.fx.length > 80) S.fx.shift();
    }
    if (S.frame % 6) return;
    for (var i = S.fx.length - 1; i >= 0; i--) {
      var e = S.fx[i], alive = true;
      try { alive = !!e.hub.gameObject.activeInHierarchy } catch (x) { alive = false }
      if (alive) continue;
      var life = now() - e.t; S.fx.splice(i, 1);
      push("fx-", { name: e.name, life: r3(life), spawnedIn: e.act, endedIn: S.act ? S.act.name : "" });
      if (life < 0.12 && S.act && e.act !== S.act.name)
        warn("effect " + e.name + " disappeared " + r3(life) + "s after spawning (" + e.act + " -> " + S.act.name + ")");
    }
  }

  // ---- compact state samples (10 per second) for timing analysis in reports -----------------------------------
  function sampleTick(p, ch) {
    var t = now(); if (!(t - S.lastSample >= 0.1)) return; S.lastSample = t;
    var c = ch[1] || {}, mp = NaN; try { mp = r3(f(p.Attr.GetMP(2))) } catch (e) {}
    S.samples.push({ t: r3(t), act: S.act ? S.act.name : "", el: S.act ? r3(S.act.el) : 0, g1: c.act ? (c.act + "@" + c.el + "/" + c.strict) : "-",
                     mute1: c.mute, mp: mp });
    if (S.samples.length > MAXS) S.samples.shift();
  }

  // ---- overlay ----------------------------------------------------------------------------------------------
  function chainLine(o) {
    return (GN[o.g] + "      ").slice(0, 7) + (STN[o.st] || o.st) + (o.act ? "  " + o.act + " " + o.el + "/" + o.strict + " (reset " + o.to + ")" : "") +
           (o.mute > 0 ? "  mute " + o.mute : "") + (o.cd > 0 ? "  cd " + o.cd : "");
  }
  function evLine(e) {
    var d = [];
    for (var k in e) if (k !== "k" && k !== "t" && k !== "fr" && k !== "wall") d.push(k + "=" + e[k]);
    return (e.t != null ? e.t.toFixed(2) : "?") + " " + e.k + " " + d.join(" ");
  }
  function overlay(ui, p, ch) {
    var dt = null; try { dt = ui.R.DebugText } catch (e) {}
    if (!dt) return;
    if (S.mode === 0) { if (S.shown) { try { dt.gameObject.SetActive(false) } catch (e) {} S.shown = false } return }
    if (S.frame % 4) return;
    var a = S.act || { name: "?", el: 0, dur: 0 }, info = actorInfo(p), L = [];
    L.push("INSPECTOR (" + (S.mode === 1 ? "light" : "detail") + ")  actor " + info.id + " " + info.logic + "   t=" + r3(now()) +
           (S.paused ? "   SIM PAUSED (F11 = step)" : "") + (SPD[S.spd] !== 1 ? "   SIM SPEED x" + SPD[S.spd] : ""));
    L.push("action " + a.name + "  " + (a.el || 0).toFixed(2) + " / " + (a.dur || 0).toFixed(2) + "s");
    if (ch[1]) L.push(chainLine(ch[1]));
    if (S.mode === 2) {
      for (var g in ch) if (+g !== 1) L.push(chainLine(ch[g]));
      var ins = [];
      for (var i = 0; i < CMD.length; i++) { var P = S.press[CMD[i][1]]; if (P) ins.push(CMD[i][1] + (P.pr ? "*" : "") + (P.open ? "(waiting)" : "")) }
      L.push("inputs " + ins.join("  ") + "   effects alive " + S.fx.length);
      var ev = S.hist.slice(-10);
      for (var j = 0; j < ev.length; j++) L.push("  " + evLine(ev[j]).slice(0, 150));
    }
    var w = S.warn.slice(S.mode === 2 ? -3 : -1);
    for (var k = 0; k < w.length; k++) L.push("! " + (w[k].t != null ? w[k].t.toFixed(2) : "") + " " + w[k].msg.slice(0, 140));
    if (S.note && now() - S.noteT < 3) L.push(S.note);
    try { dt.gameObject.SetActive(true); dt.TextAuto(L.join("\n")); S.shown = true } catch (e) {}
  }

  // ---- diagnostic report (F9) ---------------------------------------------------------------------------------
  function pad(n, w) { n = String(n); while (n.length < (w || 2)) n = "0" + n; return n }
  function textReport(r) {
    var L = ["Redux diagnostic report #" + r.mark + "   " + r.wall + "   (bbee-inspector " + VERSION + ")",
             "game build " + r.gameBuild + ", mods built " + r.modsBuilt + ": " + r.mods.map(function (m) { return m.id + " " + m.version }).join(", "),
             "player " + JSON.stringify(r.player) + "   battle time " + r.battleTime + "s (" + (S.clock || "?") + " clock)   frame " + r.frame,
             "settings " + JSON.stringify(r.settings), "",
             "Times are battle seconds (t) and wall clock (hh:mm:ss.mmm) to match a screen recording.", "", "WARNINGS"];
    r.warnings.forEach(function (w) { L.push("  " + wallStr(w.wall) + "  t=" + w.t + "  " + w.msg) });
    L.push("", "SKILL CHAINS NOW");
    for (var g in r.chains) L.push("  " + chainLine(r.chains[g]));
    L.push("", "LAST EVENTS (oldest first)");
    r.history.slice(-220).forEach(function (e) { L.push("  " + wallStr(e.wall) + "  " + evLine(e)) });
    return L.join("\r\n");
  }
  function wallStr(ms) { var d = new Date(ms); return pad(d.getHours()) + ":" + pad(d.getMinutes()) + ":" + pad(d.getSeconds()) + "." + pad(d.getMilliseconds(), 3) }
  function exportReport(p) {
    S.marks++;
    var reg = null; try { reg = require("Example").ModRegistry } catch (e) {}
    push("MARK", { n: S.marks });
    var d = new Date(), stamp = d.getFullYear() + pad(d.getMonth() + 1) + pad(d.getDate()) + "_" + pad(d.getHours()) + pad(d.getMinutes()) + pad(d.getSeconds());
    var rep = { tool: "bbee-inspector " + VERSION, mark: S.marks, wall: d.toISOString(), battleTime: r3(now()), frame: S.frame,
                gameBuild: reg ? reg.gameBuild : "?", modsBuilt: reg ? reg.built : "?", mods: reg ? reg.mods : [],
                player: p ? actorInfo(p) : null, settings: { simSpeed: SPD[S.spd], paused: S.paused, overlay: S.mode, effectFilter: S.mineOnly ? "own" : "all" },
                chains: p ? chains(p) : {}, activeEffects: S.fx.map(function (e) { return { name: e.name, since: e.t, spawnedIn: e.act } }),
                warnings: S.warn, samples: S.samples, history: S.hist,
                note: "Event history for diagnosis; this is not a deterministic replay." };
    try {
      CS.System.IO.Directory.CreateDirectory(DIAG);
      var base = DIAG + "/report_" + stamp + "_" + S.marks;
      CS.System.IO.File.WriteAllText(base + ".json", JSON.stringify(rep));
      CS.System.IO.File.WriteAllText(base + ".txt", textReport(rep));
      note("MARK " + S.marks + " saved: diag/report_" + stamp + "_" + S.marks + ".txt");
    } catch (e) { note("report export failed: " + e) }
  }

  // ---- keys and simulation control ----------------------------------------------------------------------------
  function keyTick(p) {
    var b = B();
    if (S.stepping === 2 && b) { b.TimeScale = SPD[S.spd]; S.stepping = 1 }
    else if (S.stepping === 1 && b) { b.TimeScale = 0; S.stepping = 0 }
    if (down("F8")) { S.mode = (S.mode + 1) % 3; note("overlay " + ["off", "light", "detail"][S.mode]) }
    if (down("F9")) exportReport(p);
    if (down("F10") && b) { S.paused = !S.paused; b.TimeScale = S.paused ? 0 : SPD[S.spd]; push("info", { msg: S.paused ? "simulation paused" : "simulation resumed" }); note(S.paused ? "SIMULATION PAUSED" : "simulation resumed") }
    if (down("F11") && S.paused) S.stepping = 2;
    if (down("F7") && b) { S.spd = (S.spd + 1) % SPD.length; if (!S.paused) b.TimeScale = SPD[S.spd]; push("info", { msg: "simulation speed x" + SPD[S.spd] }); note("simulation speed x" + SPD[S.spd] + " (real game time)") }
    if (down("F6")) { S.mineOnly = !S.mineOnly; note("effects: " + (S.mineOnly ? "this character only" : "everything")) }
  }

  // buff watch: stack changes of chosen buffs (e.g. a character's resource counters), with the action that caused them.
  // Characters register ids in globalThis.BBI_WATCH (array); each change is a "buff" event in the report.
  function buffTick(p) {
    var W = G.BBI_WATCH; if (!W || !W.length) return;
    var m = null; try { m = p.BuffMgr } catch (e) { return }
    S.bst = S.bst || {};
    for (var i = 0; i < W.length; i++) {
      var id = W[i], st = 0;
      try { var bf = m.Find(id); st = bf ? bf.Stack : 0 } catch (e) { st = -1 }
      var old = S.bst[id]; if (old === undefined) { S.bst[id] = st; continue }
      if (st !== old) {
        push("buff", { id: id, from: old, to: st, during: S.act ? S.act.name : "", at: S.act ? r3(S.act.el) : 0 });
        S.bst[id] = st;
      }
    }
  }

  // MP watch: every spend or gain of 3+ MP in one frame is an "mp" event with the action that caused it (Skill costs are
  // taken when the Skill starts, so a Skill that costs nothing shows up as a skill event with no mp event beside it)
  function mpTick(p) {
    var mp = NaN, mx = NaN;
    try { mp = f(p.Attr.GetMP(2)) } catch (e) {}
    try { mx = f(p.Attr.GetMPMax(2)) } catch (e) {}
    if (!isFinite(mp)) return;
    if (S.mp === undefined) { S.mp = mp; push("mp", { now: r3(mp), max: r3(mx), note: "first reading" }); return }
    var d = mp - S.mp;
    if (Math.abs(d) >= 3) push("mp", { from: r3(S.mp), to: r3(mp), delta: r3(d), max: r3(mx), during: S.act ? S.act.name : "" });
    S.mp = mp;
  }

  G.BBI_Tick = function (dt, ui) {
    try {
      S.frame++;
      var b = B(), p = b ? b.PlayerSelf : null;
