      posTick(p);
      if (!S.hooked) hookFx();
      actionTick(p);
      var ch = chains(p);
      chainTick(ch);
      inputTick(p, ch);
      hitTick(p);
      buffTick(p);
      mpTick(p);
      fxTick(p);
      sampleTick(p, ch);
      if (traceOn()) {
        var tn = now();
        if (tn - TR.ls >= 0.1 || tn < TR.ls) {
