          TR.buf.push({ k: "s", t: r3(tn), fr: S.frame, wall: Date.now(), act: S.act ? S.act.name : "", el: S.act ? r3(S.act.el) : 0, x: S.px, y: S.py, dir: S.dir });
        }
        traceFlush(false);
      }
      overlay(ui, p, ch);
    } catch (e) { if (!S.err) { S.err = true; warn("inspector error: " + (e && e.stack ? e.stack : e)) } }
  };
